/**
 * RM-MV Event Page 解析（与 Juben/src/editor/story-event-page-resolver.ts 保持逻辑一致）
 */

export type StoryEventLike = {
  eventId?: string;
  eventType?: string;
  order?: number;
  server?: {
    requirements?: unknown[];
    effects?: unknown[];
    allowedChoiceIds?: string[];
    battleRef?: string;
  };
  client?: Record<string, unknown>;
};

export type StoryEventPageContext = {
  stableEventId: (npcUid: string, ev: StoryEventLike) => string;
  isStepComplete: (npcUid: string, ev: StoryEventLike) => boolean;
  requirementsMet: (reqs: unknown[] | undefined) => boolean;
};

export type StoryAppearRequirement = {
  type?: string;
  eventId?: string;
  taskId?: number;
  varId?: string;
  value?: unknown;
};

export type StoryNpcAppear = {
  mode?: 'always' | 'conditional';
  matchMode?: 'ALL' | 'ANY';
  requirements?: StoryAppearRequirement[];
};

export function coalesceEvents(events: StoryEventLike[] | null | undefined): StoryEventLike[] {
  return events ?? [];
}

function sortedEvents(events: StoryEventLike[] | null | undefined): StoryEventLike[] {
  return [...coalesceEvents(events)].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
}

/** 线性任务链：多页同时满足时取 order 最低；互斥 gating 下与 RM-MV 一致 */
export function resolveActiveEventPage(
  npcUid: string,
  events: StoryEventLike[] | null | undefined,
  ctx: StoryEventPageContext,
): StoryEventLike | null {
  if (!coalesceEvents(events).length) return null;
  let best: StoryEventLike | null = null;
  let bestOrder = Number.MAX_SAFE_INTEGER;
  for (const ev of sortedEvents(events)) {
    if (ctx.isStepComplete(npcUid, ev)) continue;
    if (!ctx.requirementsMet(ev.server?.requirements as unknown[] | undefined)) continue;
    const ord = ev.order ?? 0;
    if (ord < bestOrder) {
      best = ev;
      bestOrder = ord;
    }
  }
  return best;
}

export function pickInteractEvent(
  npcUid: string,
  events: StoryEventLike[] | null | undefined,
  ctx: StoryEventPageContext,
): StoryEventLike | null {
  return resolveActiveEventPage(npcUid, events, ctx);
}

export function npcAppearRequirementsMet(
  appear: StoryNpcAppear | undefined,
  initialHidden: boolean | undefined,
  requirementsMet: (reqs: unknown[] | undefined) => boolean,
): boolean {
  if (appear?.mode === 'always') return true;
  if (!appear && initialHidden === false) return true;
  if (!appear && initialHidden !== true) return true;
  const mode = appear?.mode ?? (initialHidden ? 'conditional' : 'always');
  if (mode !== 'conditional') return mode === 'always';
  const reqs = appear?.requirements ?? [];
  if (!reqs.length) return false;
  const matchAny = appear?.matchMode === 'ANY';
  if (matchAny) {
    return reqs.some((r) => requirementsMet([r]));
  }
  return reqs.every((r) => requirementsMet([r]));
}

export function shouldNpcBeVisibleOnMap(
  row: { appear?: StoryNpcAppear; initialHidden?: boolean } | undefined,
  requirementsMet: (reqs: unknown[] | undefined) => boolean,
): boolean {
  if (!row) return false;
  return npcAppearRequirementsMet(row.appear, row.initialHidden, requirementsMet);
}

export function isBattleEnemyNpcUid(npcUid: string): boolean {
  return npcUid.endsWith('_enemy') || /_enemy_\d+$/.test(npcUid);
}

export function npcHasActiveStoryPage(
  npcUid: string,
  events: StoryEventLike[] | null | undefined,
  ctx: StoryEventPageContext,
): boolean {
  return resolveActiveEventPage(npcUid, events, ctx) !== null;
}
